//! The compiled resources: static tables generated by build.rs.
//!
//! Every language has one table with one pattern per slot; a slot is a
//! message value or attribute, and its index is the `Key` / `FmtKey`. Message
//! and term references are expanded at build time, so a pattern only holds
//! text, variables and selects.

/// One piece of a compiled pattern.
#[derive(Debug)]
pub(crate) enum Part {
    Text(&'static str),
    /// Index into the slot's `VARS` entry.
    Var(u8),
    /// `arms` are in source order and the first match wins, as in Fluent;
    /// `default` indexes the `*[...]` arm, taken when nothing matches.
    Select {
        var: u8,
        default: u8,
        arms: &'static [(Selector, &'static [Part])],
    },
}

/// A variant key.
#[derive(Debug)]
pub(crate) enum Selector {
    /// Matches a number of this plural category, or the category's name as a
    /// string (Fluent matches both).
    Plural(PluralCategory),
    /// Matches exactly this number.
    Exact(f64),
    /// Matches exactly this string.
    #[allow(
        dead_code,
        reason = "constructed only when a resource selects on a string"
    )]
    Str(&'static str),
}

/// CLDR cardinal plural categories used by the supported languages. A new
/// language with more categories adds them here and in build/codegen.rs.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub(crate) enum PluralCategory {
    One,
    Other,
}

impl PluralCategory {
    pub(crate) fn name(self) -> &'static str {
        match self {
            PluralCategory::One => "one",
            PluralCategory::Other => "other",
        }
    }
}

/// What kind of argument a variable takes, inferred from both languages.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub(crate) enum VarType {
    /// Selected by plural category or number: pass `Args::num`.
    Num,
    /// Selected by string: pass `Args::str`.
    #[allow(
        dead_code,
        reason = "constructed only when a resource selects on a string"
    )]
    Str,
    /// Only interpolated: either works.
    Any,
}

pub(crate) type Table = [&'static [Part]; LEN];

include!(concat!(env!("OUT_DIR"), "/table.rs"));
